import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  Img,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SplitScreenSlideProps = Record<string, any>;

const CheckmarkIcon: React.FC<{ color: string; progress: number }> = ({
  color,
  progress,
}) => {
  const pathLength = 100; // Approximate length of the check path
  const dashOffset = interpolate(progress, [0, 1], [pathLength, 0]);

  return (
    <svg
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      style={{
        overflow: "visible",
        minWidth: 24, // Prevent shrinking in flex
      }}
    >
      <circle
        cx="12"
        cy="12"
        r="12"
        fill={color}
        style={{ opacity: 0.2 }}
      />
      <path
        d="M6 12L10 16L18 8"
        stroke={color}
        strokeWidth="3"
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeDasharray={pathLength}
        strokeDashoffset={dashOffset}
      />
    </svg>
  );
};

const SplitScreenSlide: React.FC<SplitScreenSlideProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 6,
  beforeImage = "https://images.unsplash.com/photo-1493934558415-9d19f0b2b4d2?ixlib=rb-1.2.1&auto=format&fit=crop&w=1000&q=80", // Dim/Before
  afterImage = "https://images.unsplash.com/photo-1533158326339-7f3cf2404354?ixlib=rb-1.2.1&auto=format&fit=crop&w=1000&q=80", // Bright/After
  splitPercentage = 50,
  dividerColor = "#ffffff",
  accentColor = "#27ae60",
  textColor = "#ffffff",
  improvement1 = "Enhanced Clarity",
  improvement2 = "Color Correction",
  improvement3 = "Noise Reduction",
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Animation Phases
  const startDelay = 10;
  
  // 1. Wipe Animation (Slider moves from Left 0 to Split Point)
  // We want to reveal "After". 
  // Convention: Left Side = Before, Right Side = After? 
  // Let's do: Start full "Before". Wipe reveals "After" from Right to Left? 
  // Or Wipe reveals "After" from Left to Right? 
  // Let's implement: "After" is on the Right. Wipe moves from Right Edge (width) to Center.
  // Initial state: Split line is at Width (100%). "Before" fills 0-100%.
  // End state: Split line is at 50%. "Before" is 0-50%. "After" is 50%-100%.
  
  const targetSplitX = (width * splitPercentage) / 100;
  const startSplitX = width; // Start fully revealing Before (Before on Left, extends to Width)

  const wipeProgress = spring({
    frame: frame - startDelay,
    fps,
    config: { damping: 20, stiffness: 100 },
  });

  const currentSplitX = interpolate(
    wipeProgress,
    [0, 1],
    [startSplitX, targetSplitX],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 2. Checkmarks Animation (Staggered)
  const checkmarks = [improvement1, improvement2, improvement3].filter(Boolean);
  const checkmarkStartFrame = startDelay + 25; // Start after wipe settles a bit

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Montserrat" }}>
      
      {/* 
        LAYER 1: "After" Image (The result)
        Sits at the bottom, fully visible technically, but covered by Before image on top.
        Actually, let's put After on the RIGHT side.
        If we clip Before, we see After underneath.
        So Layer 1 = After (Full Screen).
      */}
      <AbsoluteFill>
        <Img
          src={afterImage}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
          }}
        />
        {/* Dark overlay on After image to make text pop? Optional. */}
        <AbsoluteFill style={{ backgroundColor: "rgba(0,0,0,0.3)" }} />
      </AbsoluteFill>

      {/* 
        LAYER 2: "Before" Image (The original)
        Sits on top. We clip it from the right side.
        Clip Rect: inset(0px [width - currentSplitX]px 0px 0px)
        This keeps the LEFT side visible up to currentSplitX.
      */}
      <AbsoluteFill
        style={{
          clipPath: `inset(0px ${width - currentSplitX}px 0px 0px)`,
          borderRight: `4px solid ${dividerColor}`, // The divider line
          filter: "grayscale(20%) brightness(0.9)", // Make Before look slightly raw
        }}
      >
        <Img
          src={beforeImage}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
          }}
        />
        {/* Label for Before */}
        <div
          style={{
            position: "absolute",
            top: 40,
            left: 40,
            backgroundColor: "rgba(0,0,0,0.6)",
            color: "#fff",
            padding: "8px 16px",
            borderRadius: 8,
            fontWeight: "bold",
            fontSize: 20,
            // UPDATED: inputRange must be monotonically increasing [0, 40] instead of [40, 0]
            opacity: interpolate(currentSplitX, [0, 40], [0, 1], {extrapolateLeft: "clamp", extrapolateRight: "clamp"}), 
          }}
        >
          BEFORE
        </div>
      </AbsoluteFill>

      {/* Label for After - positioned on the right side */}
      <div
        style={{
          position: "absolute",
          top: 40,
          right: 40,
          backgroundColor: accentColor,
          color: "#fff",
          padding: "8px 16px",
          borderRadius: 8,
          fontWeight: "bold",
          fontSize: 20,
          zIndex: 10,
          // UPDATED: inputRange must be monotonically increasing [0, 40] instead of [40, 0]
          opacity: interpolate(width - currentSplitX, [0, 40], [0, 1], {extrapolateLeft: "clamp", extrapolateRight: "clamp"}),
        }}
      >
        AFTER
      </div>

      {/* 
        LAYER 3: Checkmarks List
        Appears on the "After" side (Right side).
      */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "flex-end", // Align to right side
          paddingRight: width * 0.1, // 10% padding from right
          pointerEvents: "none",
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 24,
            width: width * 0.35, // Take up approx 35% of screen
          }}
        >
          {checkmarks.map((text, i) => {
            const delay = i * 15;
            const enter = spring({
              frame: frame - checkmarkStartFrame - delay,
              fps,
              config: { damping: 15 },
            });

            const slideIn = interpolate(enter, [0, 1], [50, 0]);
            const opacity = interpolate(enter, [0, 1], [0, 1]);

            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 16,
                  transform: `translateX(${slideIn}px)`,
                  opacity,
                }}
              >
                <div style={{ transform: `scale(${enter})` }}>
                  <CheckmarkIcon color={accentColor} progress={enter} />
                </div>
                <span
                  style={{
                    color: textColor,
                    fontSize: 28,
                    fontWeight: 600,
                    textShadow: "0px 2px 4px rgba(0,0,0,0.5)",
                  }}
                >
                  {text}
                </span>
              </div>
            );
          })}
        </div>
      </AbsoluteFill>

      {/* Draggable Handle Visual (Optional circles on the line) */}
      <div
        style={{
          position: "absolute",
          left: currentSplitX,
          top: "50%",
          transform: "translate(-50%, -50%)",
          width: 48,
          height: 48,
          backgroundColor: dividerColor,
          borderRadius: "50%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          boxShadow: "0px 4px 12px rgba(0,0,0,0.3)",
          zIndex: 20,
        }}
      >
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
          <path
            d="M8 12L4 16L8 20" // Left arrow
            stroke="#333"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          <path
            d="M16 12L20 16L16 20" // Right arrow
            stroke="#333"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          <path d="M12 4V20" stroke="#333" strokeWidth="2" strokeLinecap="round" />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default SplitScreenSlide;